{
  "items": [
    {
      "name": "Matrix.det_vandermonde",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} (v : Fin n → R),\n  (Matrix.vandermonde v).det = ∏ i, ∏ j ∈ Finset.Ioi i, (v j - v i)"
    },
    {
      "name": "Matrix.det_projVandermonde",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} (v w : Fin n → R),\n  (Matrix.projVandermonde v w).det = ∏ i, ∏ j ∈ Finset.Ioi i, (v j * w i - v i * w j)"
    },
    {
      "name": "Matrix.vandermonde",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "definition",
      "type": "{R : Type u_1} → [CommRing R] → {n : ℕ} → (Fin n → R) → Matrix (Fin n) (Fin n) R"
    },
    {
      "name": "Matrix.superFactorial_dvd_vandermonde_det",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {n : ℕ} (v : Fin (n + 1) → ℤ), ↑n.superFactorial ∣ (Matrix.vandermonde v).det"
    },
    {
      "name": "Nat.add_choose_eq",
      "module_name": "Mathlib.Data.Nat.Choose.Vandermonde",
      "kind": "theorem",
      "type": "∀ (m n k : ℕ), (m + n).choose k = ∑ ij ∈ Finset.antidiagonal k, m.choose ij.1 * n.choose ij.2"
    }
  ]
}
